import{_ as l,o as p,c as i,ae as b}from"./chunks/framework.BrEqZt6s.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/중철 묵자.md","filePath":"philosophy/중철 묵자.md"}'),o={name:"philosophy/중철 묵자.md"};function t(e,r,_,a,s,n){return p(),i("div",null,[...r[0]||(r[0]=[b("<p>겸애<br> 문제의식</p><p>원인<br> 친사, 상현<br> 해결 원리<br> 겸애<br> 정치적 적용<br> 상동, 비공<br> 규범의 초월적 근거<br> 천지, 명귀<br> 생활 경제적 처방<br> 절용, 절장, 비악, 비명<br> 정리</p><p>문제의식<br> 어떤 것이 실제로 시민과 국가에 이로운가</p><ol><li>왜 살기 힘든가? -&gt; 전쟁<br> 모든 침략전쟁을 반대, 전쟁이 사라져야 국민들이 생산활동에 종사할 수 있다</li><li>전쟁은 왜 발생하는가 -&gt; 서로 사랑하지 않아서<br> 별애에서 겸애로</li><li>국가를 어떤 기준으로 운영할 것인가<br> 혈연중심이아닌 누가 공동체의 이익을 증진시킬수 있는가</li><li>공동체의 이익을 증진하기 위해서는? 노동자의 휴식, 생산과 소비를 핵심으로 다루어야함<br> 절용, 절장, 비악 등등...</li></ol><p>친사<br> 선비를 소중하게 생각해야한다<br> 국가를 잘 운영하기 위해서는 현자를 숭상하고 능력있는 사람을 사용해야한다고 주장</p><p>현자를 등용한 후에는 반드시 높은 대우를 해주어야함. 이는 현자를 위함이 아니라 공동체의 이익을 위해서.</p><ol><li>반세습적 성격이 강하다</li><li>능력주의적 요소가 강하다</li><li>현실 행정론이 포함되어 있다</li><li>관료의 공공성을 강조</li></ol><p>묵자의 도덕성의 기준<br> 공동체의 이익을 기준으로 함<br> 유가는 묵가를 향해 실적으로 이익이 없는 도덕은 공허하다고 말함</p><ol><li>다원적 판단은 혼란을 낳음, 판단기준의 통일이 필요<br> 의견의 차이가 곧바로 사회적 혼란을 야기하는가?</li><li>규범의 통일이 강해질 수록 기준을 설정하는 자의 권력이 과도하게 커지는 것이 아닌가?<br> 결국 인간이 하늘의 뜻을 해석해야하기 때문에 이를 해석하는 상측권력에 집중하는 구조를 띔</li><li>공공의 이익 실현을 강조하는 문제의식은 타당하지만 그 목표를 실현하는 방식으로 규범의 강한 통일을 요구한 것은 과도하다고 평가<br> 공익의 필요는 잘 보았지만 그것을 다원성의 억제와 거의 같은 것으로 생각하였음<br> 오히려 최소한의 공유 규범및 해석과 실천의 다원성이 필요함</li></ol><p>법의<br> 천하의 백성을 동등하게 사랑해야함</p><p>겸애<br> 혼란의 원인이 별애에 있다<br> 서로 사랑하지 않기 때문<br> 겸상애 해라<br> 남 사랑하기를 자기 몸 사랑하듯 해라<br> 겸상애 교상리<br> 서로 사랑하고 서로 이롭게 하는 것</p><p>군주가 그것을 좋아하면 사람들은 그것을 행함<br> 가령 별애와 겸애를 주장하는 두 선비중 누구에게 내 부모를 맡기겠는가?<br> 별애를 주장하는 사람 조차도 자신에게 일이 닥치면 겸애를 주장하는 사람에게 맡긴다</p><p>평화주의자인가?<br> 침략전쟁을 비판하고, 잘못된 국가를 바로잡기 위한 정쟁이나 방어전쟁은 허용<br> 오히려 전쟁 억제의 목적<br> 의로움이 이유가 아니라 전쟁이 공공의 이익에 해를 끼치기 떄문이다</p><p>겸상애 교상리 또한 같은 맥락,</p><p>겸상애 교상리는 하늘의 뜻이다.</p><p>비명<br> 숙명론 비판<br> 성실하게 살면 하늘이 복을 내리고 그렇지 않으면 벌을 내린다.<br> 숙명론을 말하게 되면 근면성실의 동력을 잃어버린다.</p><ol><li>인간의 노력을 무력화 한다. 부유함, 가난이 모두 운명이라면 사람들은 애써도 소용없다는 생각을 가지며 통치자도 정치를 바로하려는 의지를 잃고 백성도 생업에 힘쓸 이유를 잃는다</li><li>지배층의 무책임을 정당화 할 수 있다. 국가의 문제들을 모두 운명으로 돌린다면 통치자는 자신의 잘못을 알지 못할 것이다</li><li>하늘의 뜻에 대한 올바른 이해를 막는다. 하늘을 단순한 자연 질서가 아니라 상벌을 행하고 백성을 사랑하는 도덕적 주재자이다.</li></ol>",17)])])}const m=l(o,[["render",t]]);export{d as __pageData,m as default};
